def transform(grid):
    h,w=len(grid),len(grid[0])
    out=[row[:] for row in grid]
    # Identify monochrome rectangular patches amid scattered distractor pixels.
    for color in set(v for row in grid for v in row):
        if color==max(set(v for row in grid for v in row),key=lambda v:sum(row.count(v) for row in grid)): continue
        for height in range(2,min(h,8)+1):
            for width in range(2,min(w,10)+1):
                for r in range(h-height+1):
                    for c in range(w-width+1):
                        n=sum(grid[y][x]==color for y in range(r,r+height) for x in range(c,c+width))
                        # Rectangle contents are mostly one color, damaged by speckles.
                        if n>=height*width-4 and n>=8:
                            for y in range(r,r+height):
                                for x in range(c,c+width): out[y][x]=color
